package com.mfg.crm.workflow;import com.mfg.crm.service.CrmP2Service;import com.mfg.workflow.callback.ApprovalCallback;import com.mfg.workflow.entity.WfInstance;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class CrmApprovalCallback implements ApprovalCallback{private final CrmP2Service service;public boolean supports(String t){return t.startsWith("QUOTATION")||"CONTRACT".equals(t);}public void onApproved(WfInstance i){service.approval(i.getBizId(),i.getBizType(),true);}public void onRejected(WfInstance i,String reason){service.approval(i.getBizId(),i.getBizType(),false);}}
